CardSets.register({"id":"iconic-dishes","name":"Iconic Dishes","code":"DISH","description":"420 cards of the world's defining plates — diner classics, regional staples, street snacks, celebration desserts and the breakfasts worth waking for.","theme":{"primary":"#b33a2b","secondary":"#e9a13b","artBackground":"#fff8ec","artFit":"cover"},"pack":{"name":"Iconic Dishes Pack","emblem":"🍽️","skin":"iconic-dishes"},"cards":[{"name":"Cheeseburger","rarity":"chase","id":"cheeseburger","subtitle":"American Classics","details":"A juicy grilled beef patty in a soft toasted bun, draped with melted cheese and stacked with lettuce, tomato, onion and pickles.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Cheeseburger.jpg/1280px-Cheeseburger.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Southern Fried Chicken","rarity":"legendary","id":"southern-fried-chicken","subtitle":"American Classics","details":"Chicken pieces soaked in seasoned buttermilk, dredged in spiced flour and fried until the crust turns shatteringly crisp and golden.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Aesthetic_Chicken_fry.jpg/1280px-Aesthetic_Chicken_fry.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Texas BBQ Brisket","rarity":"legendary","id":"texas-bbq-brisket","subtitle":"American Classics","details":"A whole beef brisket rubbed with salt and coarse pepper, then smoked low and slow over oak for hours until tender, barked and juicy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Plate_of_brisket%2C_BBQ_ribs%2C_pulled_pork%2C_South_Texas_beans_and_pickled_jalape%C3%B1os_from_the_Pinkerton%27s_BBQ_San_Antonio_location.jpg/1280px-Plate_of_brisket%2C_BBQ_ribs%2C_pulled_pork%2C_South_Texas_beans_and_pickled_jalape%C3%B1os_from_the_Pinkerton%27s_BBQ_San_Antonio_location.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Baby Back Ribs","rarity":"legendary","id":"baby-back-ribs","subtitle":"American Classics","details":"Tender pork ribs from high on the hog, slow-smoked or grilled and glazed until the meat pulls cleanly from the bone with each bite.","image":"https://upload.wikimedia.org/wikipedia/commons/7/78/Baby_back_ribs_-_hickory_smoked.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Philly Cheesesteak","rarity":"legendary","id":"philly-cheesesteak","subtitle":"American Classics","details":"Ribbons of sizzling beef griddled with onions and melted cheese, piled into a crusty hoagie roll — a Philadelphia sandwich icon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Philly_Cheesesteak.jpg/1280px-Philly_Cheesesteak.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"New England Clam Chowder","rarity":"legendary","id":"new-england-clam-chowder","subtitle":"American Classics","details":"A creamy, comforting chowder brimming with tender clams, diced potatoes and onion, often served with oyster crackers alongside.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Cup_of_clam_chowder%2C_with_saltines.jpg/1280px-Cup_of_clam_chowder%2C_with_saltines.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Mac and Cheese","rarity":"epic","id":"mac-and-cheese","subtitle":"American Classics","details":"Elbow macaroni folded through a rich, velvety cheese sauce and baked until bubbling, sometimes under a golden, buttery crumb top.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Mac%26cheese.jpg/1280px-Mac%26cheese.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Lobster Roll","rarity":"epic","id":"lobster-roll","subtitle":"American Classics","details":"Sweet chunks of fresh lobster lightly dressed with mayonnaise or warm butter, heaped into a toasted, split-top New England bun.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Lobster_Roll_at_the_Lobster_Claw%2C_Bar_Harbor.jpg/1280px-Lobster_Roll_at_the_Lobster_Claw%2C_Bar_Harbor.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Buffalo Wings","rarity":"epic","id":"buffalo-wings","subtitle":"American Classics","details":"Crisp-fried chicken wings tossed in a tangy, buttery hot sauce, traditionally served with celery sticks and blue cheese dressing.","image":"https://upload.wikimedia.org/wikipedia/commons/8/81/Homemade_buffalo_wings.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Shrimp and Grits","rarity":"epic","id":"shrimp-and-grits","subtitle":"American Classics","details":"Plump shrimp simmered in a savory, often bacon-flecked sauce and spooned over a bowl of creamy, stone-ground Southern grits.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d1/Last_night%27s_dinner-_bacon_wrapped_shrimp_and_grits.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Seafood Gumbo","rarity":"epic","id":"seafood-gumbo","subtitle":"American Classics","details":"A dark-roux Louisiana stew loaded with shrimp, crab and sausage, thickened and served ladled generously over steamed white rice.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Breaux_Bridge-_Frenchified_seafood_gumbo_at_Chez_Jacqueline.jpg/1280px-Breaux_Bridge-_Frenchified_seafood_gumbo_at_Chez_Jacqueline.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Jambalaya","rarity":"epic","id":"jambalaya","subtitle":"American Classics","details":"A one-pot Louisiana rice dish where sausage, chicken or seafood cooks right into tomatoey, well-seasoned grains until deeply savory.","image":"https://upload.wikimedia.org/wikipedia/commons/1/14/24_Amazing_Jambalaya.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Chicago Deep-Dish Pizza","rarity":"epic","id":"chicago-deep-dish-pizza","subtitle":"American Classics","details":"A tall, buttery crust pressed into a deep pan and layered with chunky tomato sauce and generous cheese — a knife-and-fork pizza.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Giordano%27s_Chicago_Deep_Dish_Pizza.jpg/1280px-Giordano%27s_Chicago_Deep_Dish_Pizza.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"New York-Style Pizza","rarity":"rare","id":"new-york-style-pizza","subtitle":"American Classics","details":"A thin, foldable crust with a crisp edge, bright tomato sauce and a blanket of mozzarella, sold by the giant slice across the city.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d9/New_York-Style_Pizza-crop.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Pulled Pork Sandwich","rarity":"rare","id":"pulled-pork-sandwich","subtitle":"American Classics","details":"Pork shoulder smoked until it falls apart, shredded and piled on a bun, often crowned with tangy coleslaw and a drizzle of sauce.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Pulled_pork_sandwich.jpg/1280px-Pulled_pork_sandwich.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Meatloaf","rarity":"rare","id":"meatloaf","subtitle":"American Classics","details":"Seasoned ground meat shaped into a loaf, baked until juicy and sliced thick, often under a sweet tomato glaze with mash alongside.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/MeatloafWithSauce.jpg/1280px-MeatloafWithSauce.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Chicken Pot Pie","rarity":"rare","id":"chicken-pot-pie","subtitle":"American Classics","details":"Tender chicken and vegetables in a creamy sauce, sealed under a flaky golden crust and baked until the top puffs and browns.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/2023-02-02_14_23_43_A_homemade_chicken_pot_pie_casserole_in_the_Mountainview_section_of_Ewing_Township%2C_Mercer_County%2C_New_Jersey.jpg/1280px-2023-02-02_14_23_43_A_homemade_chicken_pot_pie_casserole_in_the_Mountainview_section_of_Ewing_Township%2C_Mercer_County%2C_New_Jersey.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Yankee Pot Roast","rarity":"rare","id":"yankee-pot-roast","subtitle":"American Classics","details":"A beef chuck roast braised slowly with potatoes, carrots and onions until everything turns fork-tender in its own rich gravy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/American_pot_roast%2C_plated_up.jpg/1280px-American_pot_roast%2C_plated_up.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Texas Chili","rarity":"rare","id":"texas-chili","subtitle":"American Classics","details":"A bold bowl of beef simmered with dried chiles and spices — true Texas style skips the beans and lets the meat carry the heat.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Pot_of_Chili_Con_Carne.jpg/1280px-Pot_of_Chili_Con_Carne.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Reuben Sandwich","rarity":"rare","id":"reuben-sandwich","subtitle":"American Classics","details":"Corned beef, sauerkraut, Swiss cheese and Russian dressing grilled between slices of rye until the cheese melts into every layer.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Corn_beef_Reuben_sandwich.jpg/1280px-Corn_beef_Reuben_sandwich.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Grilled Cheese Sandwich","rarity":"rare","id":"grilled-cheese-sandwich","subtitle":"American Classics","details":"Bread buttered and griddled around melting cheese until the outside turns crisp and golden — simple, gooey and deeply comforting.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Grilled_Cheese_and_Tomato_Soup_%285899244194%29.jpg/1280px-Grilled_Cheese_and_Tomato_Soup_%285899244194%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Maryland Crab Cakes","rarity":"rare","id":"maryland-crab-cakes","subtitle":"American Classics","details":"Sweet lump crabmeat bound with just enough seasoned crumb to hold, then broiled or pan-fried into cakes with crisp, golden edges.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Chesapeake%27s_-_October_2023_-_Sarah_Stierch_05.jpg/1280px-Chesapeake%27s_-_October_2023_-_Sarah_Stierch_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Chicken-Fried Steak","rarity":"rare","id":"chicken-fried-steak","subtitle":"American Classics","details":"A tenderized beef steak dredged in seasoned flour, fried like chicken until crunchy, and smothered in creamy peppered country gravy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Chicken_Fried_Steak.jpg/1280px-Chicken_Fried_Steak.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Chicken and Dumplings","rarity":"rare","id":"chicken-and-dumplings","subtitle":"American Classics","details":"A homey stew of chicken simmered in its own broth, finished with soft, pillowy dumplings that cook right on top of the pot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/ChickenDumplings.jpg/1280px-ChickenDumplings.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Club Sandwich","rarity":"uncommon","id":"club-sandwich","subtitle":"American Classics","details":"A triple-decker of turkey or chicken, bacon, lettuce and tomato on toasted bread, cut into quarters and held together with picks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/City_Centre_Club_Sandwich_for_room_service_at_Holiday_Inn_Qingdao_City_Centre_%2820191004082448%29.jpg/1280px-City_Centre_Club_Sandwich_for_room_service_at_Holiday_Inn_Qingdao_City_Centre_%2820191004082448%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BLT Sandwich","rarity":"uncommon","id":"blt-sandwich","subtitle":"American Classics","details":"Crisp bacon, ripe tomato and cool lettuce with mayonnaise on toasted bread — a sandwich built on contrast and peak-season tomatoes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/BLT-sandwich-1.jpg/1280px-BLT-sandwich-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Sloppy Joe","rarity":"uncommon","id":"sloppy-joe","subtitle":"American Classics","details":"Ground beef simmered in a sweet-tangy tomato sauce and spooned generously over a soft bun, proudly messy exactly as the name promises.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Sloppy_Joe_%22homemade%22.jpg/1280px-Sloppy_Joe_%22homemade%22.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Salisbury Steak","rarity":"uncommon","id":"salisbury-steak","subtitle":"American Classics","details":"Seasoned beef patties shaped like little steaks, pan-seared and simmered in a savory onion and mushroom gravy until tender.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Japanese_Salisbury_steak_in_rich_brown_gravy.jpg/1280px-Japanese_Salisbury_steak_in_rich_brown_gravy.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Fried Catfish","rarity":"uncommon","id":"fried-catfish","subtitle":"American Classics","details":"Catfish fillets in a seasoned cornmeal crust, fried until crisp and flaky — a Southern fish-fry staple, often with lemon and hot sauce.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Fried_Catfish_at_Middendorf%27s.jpg/1280px-Fried_Catfish_at_Middendorf%27s.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"New England Clam Bake","rarity":"uncommon","id":"new-england-clam-bake","subtitle":"American Classics","details":"Clams, lobster, corn and potatoes steamed together, classically with seaweed by the shore, for a briny, buttery coastal feast.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/New_England_clam_bake.jpg/1280px-New_England_clam_bake.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Tater Tot Hotdish","rarity":"uncommon","id":"tater-tot-hotdish","subtitle":"American Classics","details":"A Minnesota casserole of seasoned ground beef and vegetables in a creamy sauce, crowned with a neat layer of golden tater tots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tater%20Tot%20Hot%20Dish%202008%20Winter%20Carnival%20%28cropped%29.JPG?width=1024"},{"name":"Cincinnati Chili","rarity":"uncommon","id":"cincinnati-chili","subtitle":"American Classics","details":"A finely textured, warmly spiced chili — hints of cinnamon and cocoa — ladled over spaghetti and buried under shredded cheddar.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/4-way_Cincinnati_chili_from_Camp_Washington_Chili_in_Cincinnati_OH_USA.jpg/1280px-4-way_Cincinnati_chili_from_Camp_Washington_Chili_in_Cincinnati_OH_USA.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Corn Dog","rarity":"uncommon","id":"corn-dog","subtitle":"American Classics","details":"A hot dog skewered, dipped in a thick, slightly sweet cornmeal batter and deep-fried until the coating turns crisp and golden.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/CornDog.jpg/1280px-CornDog.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Patty Melt","rarity":"uncommon","id":"patty-melt","subtitle":"American Classics","details":"A beef patty with caramelized onions and melted cheese grilled between rye slices until everything fuses into one savory bite.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Close_up_of_layers_of_patty_melt.jpg/1280px-Close_up_of_layers_of_patty_melt.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Monte Cristo Sandwich","rarity":"uncommon","id":"monte-cristo-sandwich","subtitle":"American Classics","details":"Ham, turkey and Swiss layered in bread, dipped in egg batter and griddled like French toast, then dusted with powdered sugar.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Monte_Cristo_Sandwich-1.jpg/1280px-Monte_Cristo_Sandwich-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Shrimp Po' Boy","rarity":"uncommon","id":"shrimp-po-boy","subtitle":"American Classics","details":"Crisp fried shrimp spilling out of a French roll with shredded lettuce, tomato and remoulade — a New Orleans sandwich shop classic.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f7/Shrimp_po_boy_New_Orleans.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Muffuletta","rarity":"uncommon","id":"muffuletta","subtitle":"American Classics","details":"A round Sicilian-style loaf layered with Italian cold cuts, cheese and a briny chopped olive salad, pressed until flavors meld.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Half_Muffuletta_2017-02-21_New_Orleans.jpg/1280px-Half_Muffuletta_2017-02-21_New_Orleans.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kentucky Hot Brown","rarity":"uncommon","id":"kentucky-hot-brown","subtitle":"American Classics","details":"An open-faced Louisville classic: sliced turkey on toast under a rich Mornay sauce, broiled bubbly and topped with bacon and tomato.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Hot_Brown%2C_Brown_Hotel.jpg/1280px-Hot_Brown%2C_Brown_Hotel.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Fried Clams","rarity":"uncommon","id":"fried-clams","subtitle":"American Classics","details":"Whole-belly clams in a light batter, fried until crisp outside and briny-tender inside, served with tartar sauce and a lemon wedge.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Whole_belly_clams_with_tartar_sauce_and_lemon_-_Massachusetts.jpg/1280px-Whole_belly_clams_with_tartar_sauce_and_lemon_-_Massachusetts.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Brunswick Stew","rarity":"uncommon","id":"brunswick-stew","subtitle":"American Classics","details":"A thick, tomato-based Southern stew of pulled meats, corn, lima beans and potatoes, simmered until spoon-standing hearty.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Brunswick_stew.jpg/1280px-Brunswick_stew.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Hoppin' John","rarity":"uncommon","id":"hoppin-john","subtitle":"American Classics","details":"Black-eyed peas simmered with pork and served over rice — a Lowcountry dish eaten with greens and cornbread, often for good luck.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/American_cuisine-Hopping_John-01.jpg/1280px-American_cuisine-Hopping_John-01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Skillet Cornbread","rarity":"common","id":"skillet-cornbread","subtitle":"American Classics","details":"A golden cornmeal bread baked in a sizzling cast-iron skillet so the crust turns crisp while the crumb stays tender and buttery.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skillet%20cornbread.jpg?width=640"},{"name":"Boston Baked Beans","rarity":"common","id":"boston-baked-beans","subtitle":"American Classics","details":"Navy beans slow-baked with molasses, salt pork and mustard until dark, glossy and sweet — a bean-pot tradition lasting hours.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Boston_Baked_Beans_in_Concord%2C_Mass_2012-0193.jpg/1280px-Boston_Baked_Beans_in_Concord%2C_Mass_2012-0193.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Creamy Coleslaw","rarity":"common","id":"creamy-coleslaw","subtitle":"American Classics","details":"Finely shredded cabbage and carrot folded through a creamy, lightly sweet and tangy dressing — the cool crunch beside barbecue.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Bowl%27o%27Coleslaw.jpg/1280px-Bowl%27o%27Coleslaw.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"American Potato Salad","rarity":"common","id":"american-potato-salad","subtitle":"American Classics","details":"Tender potato chunks in a creamy mayonnaise dressing with celery, onion and often chopped egg — the picnic table's anchor dish.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Kartoffelsalat_Mayonnaise_Ei.JPG/1280px-Kartoffelsalat_Mayonnaise_Ei.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Deviled Eggs","rarity":"common","id":"deviled-eggs","subtitle":"American Classics","details":"Hard-boiled egg whites filled with their own yolks whipped with mayonnaise and mustard, dusted with paprika for a two-bite classic.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Deviled_Eggs_on_Plate.jpg/1280px-Deviled_Eggs_on_Plate.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Green Bean Casserole","rarity":"common","id":"green-bean-casserole","subtitle":"American Classics","details":"Green beans baked in a creamy mushroom sauce under a crown of crisp fried onions — a holiday table fixture since the 1950s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/2020-11-26_04_21_45_A_sample_of_Wegman%27s_green_bean_casserole_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg/1280px-2020-11-26_04_21_45_A_sample_of_Wegman%27s_green_bean_casserole_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Sweet Potato Casserole","rarity":"common","id":"sweet-potato-casserole","subtitle":"American Classics","details":"Whipped sweet potatoes baked under a toasted marshmallow or pecan-crumble top — the sweetest regular on the holiday table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Toasted%20Marshmallow%20on%20Mashed%20Sweet%20Potato%20(43469825985).jpg?width=1024"},{"name":"Buttered Corn on the Cob","rarity":"common","id":"buttered-corn-on-the-cob","subtitle":"American Classics","details":"Sweet corn boiled, steamed or grilled in its husk and served hot with melting butter and salt — summer eaten straight off the cob.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Buttered_Corn_%2828566406544%29.jpg/1280px-Buttered_Corn_%2828566406544%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Fried Green Tomatoes","rarity":"common","id":"fried-green-tomatoes","subtitle":"American Classics","details":"Firm, unripe tomato slices in a cornmeal crust, fried crisp and tangy, often served with a creamy remoulade for dipping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fried%20green%20tomatoes.jpg?width=1024"},{"name":"Hush Puppies","rarity":"common","id":"hush-puppies","subtitle":"American Classics","details":"Golden balls of seasoned cornmeal batter, deep-fried until crisp outside and fluffy inside — born to sit beside fried seafood.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Fried_Green_Tomatoes_with_ranch_dressing.jpg/1280px-Fried_Green_Tomatoes_with_ranch_dressing.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Spoonbread","rarity":"common","id":"spoonbread","subtitle":"American Classics","details":"A soft, souffle-like cornmeal bread from the South, baked until puffed and spooned straight from the dish while still warm.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Fluffy_Spoonbread.jpg/1280px-Fluffy_Spoonbread.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Minnesota Wild Rice Soup","rarity":"common","id":"minnesota-wild-rice-soup","subtitle":"American Classics","details":"A creamy soup built on Minnesota's nutty wild rice, usually with chicken, vegetables and a whisper of spice in every spoonful.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Chicken_and_wild_rice_soup%2C_Famous_Dave%27s_Bozeman%2C_Montana.jpg/1280px-Chicken_and_wild_rice_soup%2C_Famous_Dave%27s_Bozeman%2C_Montana.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kentucky Burgoo","rarity":"common","id":"kentucky-burgoo","subtitle":"American Classics","details":"Kentucky's famously thick communal stew of mixed meats and garden vegetables, simmered for hours until rich and hearty.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Kentucky_burgoo.jpg/1280px-Kentucky_burgoo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Cioppino","rarity":"common","id":"cioppino","subtitle":"American Classics","details":"A San Francisco tomato-and-wine seafood stew brimming with crab, clams, shrimp and fish, made for dunking crusty sourdough.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Carthay_Shellfish_Cioppino_%2829428097276%29.jpg/1280px-Carthay_Shellfish_Cioppino_%2829428097276%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Crab Louie Salad","rarity":"common","id":"crab-louie-salad","subtitle":"American Classics","details":"A West Coast salad of sweet crab piled over crisp lettuce with egg and tomato, dressed in a creamy, chili-kissed Louie dressing.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6c/Crab_Louie_Salad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Waldorf Salad","rarity":"common","id":"waldorf-salad","subtitle":"American Classics","details":"Crisp apples, celery and grapes in a creamy dressing, often with walnuts — a salad associated with New York's Waldorf hotel.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Waldorf_Salad.jpg/1280px-Waldorf_Salad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Cobb Salad","rarity":"common","id":"cobb-salad","subtitle":"American Classics","details":"Neat rows of chicken, bacon, egg, tomato, avocado and blue cheese over greens — a composed salad said to hail from Hollywood.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a6/Brown_Derby_Cobb_Salad_%282440195933%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Chef Salad","rarity":"common","id":"chef-salad","subtitle":"American Classics","details":"A generous plate of greens topped with strips of ham, turkey, cheese and hard-boiled egg — a full meal disguised as a salad.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Chef_Salad.JPG/1280px-Chef_Salad.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ambrosia Salad","rarity":"common","id":"ambrosia-salad","subtitle":"American Classics","details":"A fluffy Southern fruit salad of oranges, pineapple, coconut and marshmallows folded into cream — part side dish, part dessert.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3c/Ambrosia_salad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Watergate Salad","rarity":"common","id":"watergate-salad","subtitle":"American Classics","details":"A pastel-green fluff of pistachio pudding, crushed pineapple, marshmallows and whipped topping, beloved at potlucks for decades.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0a/Watergate_salad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Fry Bread","rarity":"common","id":"fry-bread","subtitle":"American Classics","details":"Pillowy rounds of dough fried until puffed and golden, eaten plain, with honey, or as the base for tacos and savory toppings.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Frybread_-_July_2009_-_Sarah_Stierch.jpg/1280px-Frybread_-_July_2009_-_Sarah_Stierch.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Spam Musubi","rarity":"common","id":"spam-musubi","subtitle":"American Classics","details":"A slice of grilled Spam on a block of rice, wrapped with nori like oversized sushi — Hawaii's beloved grab-and-go snack.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Homemade_Spam_Musubi.jpg/1280px-Homemade_Spam_Musubi.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Loco Moco","rarity":"common","id":"loco-moco","subtitle":"American Classics","details":"A Hawaiian plate of rice topped with a hamburger patty, rich brown gravy and a fried egg — comfort food with a runny-yolk crown.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Homestyle_Hawaiian_loco_moco_-_1.jpg/1280px-Homestyle_Hawaiian_loco_moco_-_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Seven-Layer Salad","rarity":"common","id":"seven-layer-salad","subtitle":"American Classics","details":"A glass-bowl salad stacked in stripes — lettuce, peas, celery, bacon, cheese and a creamy top — made to show off its layers.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a3/Seven_layer_salad.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Pizza Napoletana","rarity":"chase","id":"pizza-napoletana","subtitle":"European Classics","details":"Naples' gift to the world: a soft, blistered crust with San Marzano-style tomato, fresh mozzarella and basil, baked fiercely hot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Pizza-napoletana.jpg/1280px-Pizza-napoletana.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Paella Valenciana","rarity":"chase","id":"paella-valenciana","subtitle":"European Classics","details":"Valencia's celebrated rice, cooked in a wide shallow pan with meats, beans and vegetables until the prized crisp socarrat forms.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/01_Paella_Valenciana_original.jpg/1280px-01_Paella_Valenciana_original.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Spaghetti Carbonara","rarity":"legendary","id":"spaghetti-carbonara","subtitle":"European Classics","details":"Rome's silky pasta of eggs, Pecorino Romano, guanciale and black pepper, tossed off the heat so the sauce turns glossy, never scrambled.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Spaghetti_Carbonara_von_Unico_Tauberbischofsheim_2.jpg/1280px-Spaghetti_Carbonara_von_Unico_Tauberbischofsheim_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Lasagne alla Bolognese","rarity":"legendary","id":"lasagne-alla-bolognese","subtitle":"European Classics","details":"Sheets of pasta layered with slow-simmered beef ragù and creamy béchamel, baked until the corners crisp and the middle melds.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Lasagna_bolognese.jpg/1280px-Lasagna_bolognese.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Beef Wellington","rarity":"legendary","id":"beef-wellington","subtitle":"European Classics","details":"Beef fillet wrapped in mushroom duxelles and golden puff pastry, baked until the crust shatters and the center stays rosy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/11-28-2024_Beef_Wellington_-_001.jpg/1280px-11-28-2024_Beef_Wellington_-_001.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Coq au Vin","rarity":"legendary","id":"coq-au-vin","subtitle":"European Classics","details":"Chicken braised slowly in red wine with mushrooms, pearl onions and lardons, until the meat turns tender and the sauce deep and glossy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gourmet_coq_au_vin.jpg?width=1024"},{"name":"French Onion Soup","rarity":"legendary","id":"french-onion-soup","subtitle":"European Classics","details":"A rich beef broth ladled over caramelised onions and toasted bread, then blanketed with Gruyère and broiled until bubbling and golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Soupe_%C3%A0_l%27oignon.jpg?width=1024"},{"name":"Ratatouille","rarity":"legendary","id":"ratatouille","subtitle":"European Classics","details":"Provençal vegetables — aubergine, courgette, peppers and tomatoes — simmered with olive oil and herbs into a soft, sunny stew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ratatouille_home_cooked.jpg?width=1024"},{"name":"Risotto alla Milanese","rarity":"epic","id":"risotto-alla-milanese","subtitle":"European Classics","details":"Carnaroli rice stirred to a creamy flow with saffron, stock, butter and Parmesan; the saffron gives Milan's risotto its golden colour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Risotto%20alla%20Milanese.JPG?width=1024"},{"name":"Osso Buco","rarity":"epic","id":"osso-buco","subtitle":"European Classics","details":"Braised veal shank cut across the bone, served in its rich cooking juices, often with gremolata and the marrow prized from the centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ossobuco.jpg?width=1024"},{"name":"Wiener Schnitzel","rarity":"epic","id":"wiener-schnitzel","subtitle":"European Classics","details":"A thin veal cutlet in a crisp golden breadcrumb crust, fried in butter or lard and served simply with lemon, parsley and potatoes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wiener-Schnitzel02.jpg?width=1024"},{"name":"Beef Stroganoff","rarity":"epic","id":"beef-stroganoff","subtitle":"European Classics","details":"Strips of beef and mushrooms folded into a tangy sour-cream sauce, served over noodles or rice; a dish long associated with Russia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moscow_%288351271825%29.jpg?width=1024"},{"name":"Moussaka","rarity":"epic","id":"moussaka","subtitle":"European Classics","details":"Layers of aubergine, spiced minced meat and tomatoes under a thick béchamel, baked until set and golden — a Greek casserole classic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MussakasMeMelitsanesKePatates01.JPG?width=1024"},{"name":"Fish and Chips","rarity":"epic","id":"fish-and-chips","subtitle":"European Classics","details":"Batter-crisped white fish with thick-cut chips, salt and malt vinegar; a seaside and chip-shop staple long associated with Britain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fish_and_chips_blackpool.jpg?width=1024"},{"name":"Shepherd's Pie","rarity":"epic","id":"shepherds-pie","subtitle":"European Classics","details":"Minced lamb simmered with vegetables in gravy under a fork-ridged blanket of mashed potato, baked until the top turns crisp at the edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg?width=1024"},{"name":"Bouillabaisse","rarity":"epic","id":"bouillabaisse","subtitle":"European Classics","details":"A Provençal fisherman's stew of mixed fish and shellfish in a saffron and fennel broth, served with rouille-topped toasts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bouillabaisse%20at%20restaurant%20Belge.jpg?width=1024"},{"name":"Bangers and Mash","rarity":"rare","id":"bangers-and-mash","subtitle":"European Classics","details":"Plump pork sausages over a mound of mashed potato with rich onion gravy — a hearty British pub plate built on simple comforts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bangers%20and%20mash%20with%20peas.jpg?width=1024"},{"name":"Hungarian Goulash","rarity":"rare","id":"hungarian-goulash","subtitle":"European Classics","details":"Beef simmered low and slow with onions and sweet paprika into a deep red stew, Hungary's beloved gulyás, often served with noodles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gulyas080.jpg?width=1024"},{"name":"Pierogi","rarity":"rare","id":"pierogi","subtitle":"European Classics","details":"Tender half-moon dumplings with fillings such as potato and cheese, sauerkraut or meat, boiled and glossed with butter and onions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pierogi_z_mas%C5%82em_-_2023.03.31.jpg?width=1024"},{"name":"Cacio e Pepe","rarity":"rare","id":"cacio-e-pepe","subtitle":"European Classics","details":"Rome's three-ingredient marvel: tonnarelli or spaghetti tossed with black pepper and Pecorino Romano into a sharp, creamy coating.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cacio%20e%20pepe.jpg?width=1024"},{"name":"Chicken Kiev","rarity":"rare","id":"chicken-kiev","subtitle":"European Classics","details":"A crumbed chicken breast wrapped around chilled garlic-herb butter, so the centre melts and spills out when the crisp crust is cut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chicken_Kiev_-_Ukrainian_East_Village_restaurant.jpg?width=1024"},{"name":"Steak Tartare","rarity":"rare","id":"steak-tartare","subtitle":"European Classics","details":"Hand-chopped raw beef seasoned and shaped with a raw egg yolk on top, plus capers, mustard and onion; a French bistro classic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Classic_steak_tartare.jpg?width=1024"},{"name":"Swiss Cheese Fondue","rarity":"rare","id":"swiss-cheese-fondue","subtitle":"European Classics","details":"Gruyère and Emmental melted with white wine in a shared pot, kept warm over a flame while diners swirl in cubes of crusty bread.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheese%20fondue-01-a.jpg?width=1024"},{"name":"Cassoulet","rarity":"rare","id":"cassoulet","subtitle":"European Classics","details":"White beans baked slowly with duck confit, pork and sausage under a rich crust, in the style of southwestern France's Castelnaudary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bowl_of_cassoulet.JPG?width=1024"},{"name":"Sauerbraten","rarity":"rare","id":"sauerbraten","subtitle":"European Classics","details":"Beef marinated for days in a sweet-sour spiced vinegar sauce, then braised and served sliced with its gingery gravy and dumplings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heldrunger_Sauerbraten_2.JPG?width=1024"},{"name":"Escargots de Bourgogne","rarity":"rare","id":"escargots-de-bourgogne","subtitle":"European Classics","details":"Snails baked in their shells under a bubbling blanket of garlic, parsley and herb butter, mopped up with bread in Burgundian style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Escargots%20de%20Bourgogne%203.JPG?width=1024"},{"name":"Raclette","rarity":"rare","id":"raclette","subtitle":"European Classics","details":"A wheel of Alpine cheese warmed until the surface melts, then scraped in ribbons over potatoes, pickles and cured meats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Raclette_20040817_140816.jpg?width=1024"},{"name":"Tartiflette","rarity":"rare","id":"tartiflette","subtitle":"European Classics","details":"A Savoie gratin of potatoes, reblochon cheese, onions and lardons, baked until the cheese melts into a rich, golden crust.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Une_tartiflette_sortie_du_four.jpg?width=1024"},{"name":"Spaghetti Aglio e Olio","rarity":"rare","id":"spaghetti-aglio-e-olio","subtitle":"European Classics","details":"Spaghetti tossed in olive oil gently warmed with sliced garlic and chilli flakes — Naples' minimalist late-night pantry pasta.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spaghetti%20aglio%20e%20olio%20KB.jpg?width=1024"},{"name":"Duck Confit","rarity":"uncommon","id":"duck-confit","subtitle":"European Classics","details":"Duck legs salt-cured, then poached slowly in their own fat until silky inside, and crisped skin-side in a pan before serving.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Duck%20Confit%20%283375036024%29.jpg?width=1024"},{"name":"Blanquette de Veau","rarity":"uncommon","id":"blanquette-de-veau","subtitle":"European Classics","details":"Veal simmered gently and served in a pale, velvety white sauce with mushrooms and pearl onions — a cornerstone of French cooking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blanquette%20de%20veau%20%C3%A0%20l%27ancienne%2006.jpg?width=1024"},{"name":"Sole Meunière","rarity":"uncommon","id":"sole-meuniere","subtitle":"European Classics","details":"Whole or filleted sole dusted in flour, fried in foaming butter and finished with lemon, parsley and browned butter at the table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sole%20meuniere%20%284689490702%29.jpg?width=1024"},{"name":"Saltimbocca alla Romana","rarity":"uncommon","id":"saltimbocca-alla-romana","subtitle":"European Classics","details":"Thin veal escalopes layered with prosciutto and sage, pan-fried and deglazed with white wine; its name means 'jumps in the mouth'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saltimbocca_01.jpg?width=1024"},{"name":"Vitello Tonnato","rarity":"uncommon","id":"vitello-tonnato","subtitle":"European Classics","details":"Cold sliced veal under a smooth, tuna and caper mayonnaise sauce, served chilled as a Piedmontese antipasto for warm days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vitello%20tonnato%20%286977537544%29.jpg?width=1024"},{"name":"Trofie al Pesto","rarity":"uncommon","id":"trofie-al-pesto","subtitle":"European Classics","details":"Small twisted Ligurian pasta coated in vivid basil pesto with green beans and potatoes, in the traditional Genovese manner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trofie%20al%20pesto%2007.jpg?width=1024"},{"name":"Insalata Caprese","rarity":"uncommon","id":"insalata-caprese","subtitle":"European Classics","details":"Thick slices of tomato and fresh mozzarella layered with basil leaves and olive oil — a Capri salad in Italy's flag colours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caprese-1_%28tigher_crop%29.jpg?width=1024"},{"name":"Greek Salad","rarity":"uncommon","id":"greek-salad","subtitle":"European Classics","details":"Chopped tomatoes, cucumber, peppers and red onion with olives and a slab of feta, dressed simply with olive oil and oregano.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Greece_Food_Horiatiki.JPG?width=1024"},{"name":"Spanakopita","rarity":"uncommon","id":"spanakopita","subtitle":"European Classics","details":"Crisp layers of buttered filo wrapped around a spinach and feta filling, baked until flaky and golden in Greek home style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spanakopita.jpg?width=1024"},{"name":"Dolmades","rarity":"uncommon","id":"dolmades","subtitle":"European Classics","details":"Tender grape leaves rolled around a seasoned filling of rice, herbs and sometimes meat, served with lemon across the eastern Mediterranean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dolmades%20Kurdish%20and%20Greek%20-%20Dec%202018.jpg?width=1024"},{"name":"Souvlaki","rarity":"uncommon","id":"souvlaki","subtitle":"European Classics","details":"Skewers of marinated pork or chicken grilled over charcoal, served with pita, tomato, onion and tzatziki on Greek streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%CE%95%CE%BB%CE%BB%CE%B7%CE%BD%CE%B9%CE%BA%CF%8C_%CE%A3%CE%BF%CF%85%CE%B2%CE%BB%CE%AC%CE%BA%CE%B9_-_panoramio.jpg?width=1024"},{"name":"Pastitsio","rarity":"uncommon","id":"pastitsio","subtitle":"European Classics","details":"A Greek baked pasta of tube noodles and spiced meat sauce under thick béchamel, sliced into generous squares like lasagne's cousin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pastitsio_homemade.jpg?width=1024"},{"name":"Ribollita","rarity":"uncommon","id":"ribollita","subtitle":"European Classics","details":"A Tuscan bread soup of tomatoes, cannellini beans, kale and stale bread, simmered twice — ribollita means 'reboiled'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ribollita_Siena.jpg?width=1024"},{"name":"Minestrone","rarity":"uncommon","id":"minestrone","subtitle":"European Classics","details":"A hearty Italian vegetable soup built on beans, seasonal greens, pasta or rice and a Parmesan rind, finished with olive oil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Liat%20Portal%20for%20Foodie%20Disorder%20-%20Homemade%20minestrone%20soup.jpg?width=1024"},{"name":"Borscht","rarity":"uncommon","id":"borscht","subtitle":"European Classics","details":"A vivid beetroot soup from Eastern Europe, served hot with a swirl of sour cream; its colour and gentle sweetness define it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Borscht_served.jpg?width=1024"},{"name":"Pelmeni","rarity":"uncommon","id":"pelmeni","subtitle":"European Classics","details":"Small Siberian-style meat dumplings, boiled and served with butter, sour cream or a splash of vinegar and black pepper.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pelmeni_Russian.jpg?width=1024"},{"name":"Blini","rarity":"uncommon","id":"blini","subtitle":"European Classics","details":"Thin yeasted pancakes from Slavic kitchens, folded around fillings or served with sour cream, jam, or caviar for celebrations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/50_%D0%B1%D0%BB%D1%96%D0%BD%D0%BA%D0%BE%D1%9E_%D0%BD%D0%B0_%D1%82%D0%B0%D0%BB%D0%B5%D1%80%D1%86%D1%8B_240_%D0%BC%D0%BC.jpg?width=1024"},{"name":"Irish Stew","rarity":"uncommon","id":"irish-stew","subtitle":"European Classics","details":"A slow simmer of lamb or beef with potatoes, carrots and onions in a light broth — Ireland's rustic one-pot farmhouse stew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Irish_Beef_Stew_%2834046928633%29.jpg?width=1024"},{"name":"Colcannon","rarity":"uncommon","id":"colcannon","subtitle":"European Classics","details":"Mashed potato folded with kale or cabbage, butter and scallions, often fried in patties; a thrifty Irish favourite at Halloween.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colcannon.JPG?width=1024"},{"name":"Lancashire Hotpot","rarity":"uncommon","id":"lancashire-hotpot","subtitle":"European Classics","details":"Sliced potatoes layered over lamb or beef in a deep pot, covered with a crisp potato top and baked slowly in Lancashire style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lancashire_hotpot.jpg?width=1024"},{"name":"Cottage Pie","rarity":"common","id":"cottage-pie","subtitle":"European Classics","details":"Minced beef and vegetables in gravy under mashed potato — shepherd's pie's beef counterpart, baked until the ridges brown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Australian%20cottage%20pie%20%28cropped%29.jpg?width=1024"},{"name":"Toad in the Hole","rarity":"common","id":"toad-in-the-hole","subtitle":"European Classics","details":"Sausages baked into a puffed Yorkshire pudding batter, served with onion gravy; the batter rises around the sausages in the oven.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Toad_in_the_hole.jpg?width=1024"},{"name":"Steak and Ale Pie","rarity":"common","id":"steak-and-ale-pie","subtitle":"European Classics","details":"Chunks of beef braised in ale under a golden pastry lid, a pub favourite where the filling stays rich, dark and savoury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Goddards%20steak%20and%20ale%20pie.jpg?width=1024"},{"name":"Cornish Pasty","rarity":"common","id":"cornish-pasty","subtitle":"European Classics","details":"A sturdy half-moon of shortcrust pastry crimped around beef, potato, swede and onion, baked for miners' lunches in Cornwall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cornish_Pasty_%28cropped%29.jpeg?width=1024"},{"name":"Scotch Egg","rarity":"common","id":"scotch-egg","subtitle":"European Classics","details":"A hard-boiled egg wrapped in sausage meat, crumbed and fried until crisp, eaten cold on picnics or warm with a salad.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/One_scotch_egg_%28No_jar_of_Marmite%29.jpg?width=1024"},{"name":"Ploughman's Lunch","rarity":"common","id":"ploughmans-lunch","subtitle":"European Classics","details":"A rustic board of crusty bread, farmhouse cheese, pickles, chutney, apple and salad — the English pub's classic cold lunch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/An%20Elsecar%20Ploughman%27s%20Lunch.jpg?width=1024"},{"name":"Croque Monsieur","rarity":"common","id":"croque-monsieur","subtitle":"European Classics","details":"A toasted ham and cheese sandwich under a creamy béchamel and browned cheese crust, served in Parisian cafés since the belle époque.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Croque_monsieur.jpg?width=1024"},{"name":"Croque Madame","rarity":"common","id":"croque-madame","subtitle":"European Classics","details":"The croque monsieur crowned with a fried or poached egg, whose yolk is said to resemble a lady's hat in Parisian café lore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Croque-madame%20at%20cafe%20kocsi.jpg?width=1024"},{"name":"Jansson's Temptation","rarity":"common","id":"janssons-temptation","subtitle":"European Classics","details":"A Swedish gratin of potatoes, onions and sprats layered with cream and breadcrumbs, baked until golden for festive tables.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Janssons_frestelse.jpg?width=1024"},{"name":"Swedish Meatballs","rarity":"common","id":"swedish-meatballs","subtitle":"European Classics","details":"Small seasoned beef and pork meatballs in a creamy gravy, served with mashed potatoes, lingonberry jam and pickled cucumber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6ttbullar%20-%20Mama%27s%20Meetballs%202024-02-11.jpg?width=1024"},{"name":"Gravlax","rarity":"common","id":"gravlax","subtitle":"European Classics","details":"Salmon cured with salt, sugar and dill until silky, sliced thin and served on rye with a sweet mustard-dill sauce in Scandinavia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Laxr%C3%A4tter.jpg?width=1024"},{"name":"Pickled Herring","rarity":"common","id":"pickled-herring","subtitle":"European Classics","details":"Herring preserved in spiced vinegar brine, served with onions on rye or with potatoes — a cornerstone of northern European tables.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pickled%20herring%20%28Poznan%29.JPG?width=1024"},{"name":"Frikadeller","rarity":"common","id":"frikadeller","subtitle":"European Classics","details":"Danish pan-fried pork meatballs, oval and golden, made with milk-soaked breadcrumbs and served with potatoes and brown sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frikadeller.jpg?width=1024"},{"name":"Spaetzle","rarity":"common","id":"spaetzle","subtitle":"European Classics","details":"Soft German egg noodles pressed or scraped into boiling water, tossed in butter and served with roasts, cheese or lentils.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sp%C3%A4tzle-02.jpg?width=1024"},{"name":"Rouladen","rarity":"common","id":"rouladen","subtitle":"European Classics","details":"Beef rolled around bacon, onion and pickle, braised in a rich gravy until tender — a Sunday centrepiece in German homes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Klosterst%C3%BCbel%20St.%20Marienstern%20-%20Rinderroulade%20mit%20Rotkohl.jpg?width=1024"},{"name":"German Potato Salad","rarity":"common","id":"german-potato-salad","subtitle":"European Classics","details":"Sliced potatoes in a warm bacon and vinegar dressing with onion and herbs, served at German beer gardens and picnics alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Warm%20potato%20salad%20with%20ham.jpg?width=1024"},{"name":"Carbonnade Flamande","rarity":"common","id":"carbonnade-flamande","subtitle":"European Classics","details":"Beef braised slowly in dark beer with onions and a slice of spiced bread, Belgium's sweet-savoury Flemish carbonnade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jielbeaumadier%20carbonade%20flamande%202010.jpg?width=1024"},{"name":"Waterzooi","rarity":"common","id":"waterzooi","subtitle":"European Classics","details":"A gentle Ghent stew of chicken or fish poached in a creamy vegetable broth, thickened with egg yolk and cream at the end.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Waterzooi%20%28Fastaff%29.jpg?width=1024"},{"name":"Moules-Frites","rarity":"common","id":"moules-frites","subtitle":"European Classics","details":"A brimming pot of mussels steamed in white wine or beer, served with crisp golden frites and mayonnaise — Belgium's national plate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moules%20Frites.jpg?width=1024"},{"name":"Hutspot","rarity":"common","id":"hutspot","subtitle":"European Classics","details":"A Dutch mash of potatoes, carrots and onions, traditionally served with smoked sausage; its name means 'hotchpotch'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hutspot_in_pan.JPG?width=1024"},{"name":"Erwtensoep","rarity":"common","id":"erwtensoep","subtitle":"European Classics","details":"A thick Dutch split-pea soup with pork and smoked sausage, so dense a spoon can stand in it, eaten with rye bread in winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Erwtensoep%20roggebrood%20katenspek.jpg?width=1024"},{"name":"Bacalhau à Brás","rarity":"common","id":"bacalhau-a-bras","subtitle":"European Classics","details":"Salt cod shredded and scrambled with eggs, matchstick potatoes, onions and olives — Lisbon's golden, comforting bacalhau dish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bacalhau_a_Bras.jpg?width=1024"},{"name":"Francesinha","rarity":"common","id":"francesinha","subtitle":"European Classics","details":"Porto's towering toasted sandwich layered with meats and cheese, blanketed in a spicy tomato and beer sauce, often with fries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Francesinha_Sandwich_%28cropped%29.jpg?width=1024"},{"name":"Caldo Verde","rarity":"common","id":"caldo-verde","subtitle":"European Classics","details":"A Portuguese soup of potato purée with finely shredded kale and slices of chouriço, finished with a thread of olive oil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caldo_verde.jpg?width=1024"},{"name":"Piri Piri Chicken","rarity":"common","id":"piri-piri-chicken","subtitle":"European Classics","details":"Chicken marinated in fiery piri piri chilli, garlic and lemon, then grilled until charred at the edges, in Portuguese style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2018-02-03%20Chicken%20Piri-Piri%2C%20Albufeira%20%281%29.JPG?width=1024"},{"name":"Fettuccine Alfredo","rarity":"common","id":"fettuccine-alfredo","subtitle":"European Classics","details":"Ribbons of fettuccine folded through butter and Parmesan until glossy — a Roman preparation made famous in restaurants worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fettuccine_Alfredo_originals.jpg?width=1024"},{"name":"Sushi","rarity":"chase","id":"sushi","subtitle":"Asian Classics","details":"Seasoned rice paired with fresh seafood, vegetables or egg, formed as nigiri or rolls and eaten with soy sauce, wasabi and pickled ginger.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sushi_platter.jpg?width=1024"},{"name":"Tonkotsu Ramen","rarity":"chase","id":"tonkotsu-ramen","subtitle":"Asian Classics","details":"Springy noodles in a rich, cloudy pork-bone broth, topped with sliced chashu pork, scallions, nori and a seasoned soft egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tonkotsu_ramen.JPG?width=1024"},{"name":"Phở Bò","rarity":"chase","id":"pho-bo","subtitle":"Asian Classics","details":"Vietnamese noodle soup of clear spiced beef broth, flat rice noodles and thin beef slices, finished with fresh herbs, lime and chilli.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pho%20Bo%20%28Noodle%20with%20beef%29%20%282656424326%29.jpg?width=1024"},{"name":"Peking Duck","rarity":"chase","id":"peking-duck","subtitle":"Asian Classics","details":"Roast duck prized for its crisp, lacquered skin, carved at the table and eaten in thin pancakes with hoisin sauce, cucumber and scallion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bianyifang%20duck.jpg?width=1024"},{"name":"Pad Thai","rarity":"legendary","id":"pad-thai","subtitle":"Asian Classics","details":"Stir-fried rice noodles in a sweet, sour and savoury tamarind sauce, tossed with egg, prawns or chicken, bean sprouts, chives and peanuts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phat_Thai_kung_Chang_Khien_street_stall.jpg?width=1024"},{"name":"Hyderabadi Biryani","rarity":"legendary","id":"hyderabadi-biryani","subtitle":"Asian Classics","details":"Fragrant long-grain rice layered with spiced meat and fried onions, sealed and slow-cooked so the saffron and whole spices perfume every grain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hyderabadi_Chicken_Biryani.jpg?width=1024"},{"name":"Tom Yum Goong","rarity":"legendary","id":"tom-yum-goong","subtitle":"Asian Classics","details":"Hot and sour Thai prawn soup fragrant with lemongrass, galangal, lime leaves and chilli, brightened with lime juice and fish sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tom_yam_kung_maenam.jpg?width=1024"},{"name":"Butter Chicken","rarity":"legendary","id":"butter-chicken","subtitle":"Asian Classics","details":"Tandoor-roasted chicken folded into a silky tomato, butter and cream sauce with fenugreek, served with naan or rice for scooping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg?width=1024"},{"name":"Chicken Tikka Masala","rarity":"legendary","id":"chicken-tikka-masala","subtitle":"Asian Classics","details":"Char-grilled marinated chicken pieces simmered in a spiced, creamy tomato sauce; a restaurant favourite strongly associated with Britain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chicken_tikka_masala_%28cropped%29.jpg?width=1024"},{"name":"Thai Green Curry","rarity":"legendary","id":"thai-green-curry","subtitle":"Asian Classics","details":"Chicken, aubergine and bamboo shoots simmered in coconut milk and green curry paste, perfumed with Thai basil, lime leaf and chilli.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thai_green_chicken_curry_and_roti.jpg?width=1024"},{"name":"Har Gow","rarity":"legendary","id":"har-gow","subtitle":"Asian Classics","details":"Steamed prawn dumplings in delicate, translucent rice-wheat wrappers, a dim sum classic served in bamboo steamers with soy sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steamed_prawn_dumplings.jpg?width=1024"},{"name":"Kung Pao Chicken","rarity":"epic","id":"kung-pao-chicken","subtitle":"Asian Classics","details":"Diced chicken stir-fried with dried chillies, Sichuan peppercorns, peanuts and scallions in a dark, tangy sauce with a gentle tingle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kung-pao-shanghai.jpg?width=1024"},{"name":"Mapo Tofu","rarity":"epic","id":"mapo-tofu","subtitle":"Asian Classics","details":"Soft tofu cubes braised in a fiery chilli-bean sauce with minced pork and Sichuan pepper, delivering the famous málà numbing heat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chen_Mapo_Tofu.jpg?width=1024"},{"name":"Bibimbap","rarity":"epic","id":"bibimbap","subtitle":"Asian Classics","details":"Warm rice topped with seasoned vegetables, beef, a fried egg and gochujang, mixed at the table; served crisp-bottomed in a hot stone pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dolsot-bibimbap.jpg?width=1024"},{"name":"Bulgogi","rarity":"epic","id":"bulgogi","subtitle":"Asian Classics","details":"Thin slices of beef marinated in soy sauce, pear, garlic and sesame, then grilled until caramelised and eaten with rice or in lettuce wraps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bulgogi_2.jpg?width=1024"},{"name":"Beef Rendang","rarity":"epic","id":"beef-rendang","subtitle":"Asian Classics","details":"Beef slowly braised in coconut milk and a paste of chillies, lemongrass and galangal until the sauce darkens, thickens and coats the meat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rendang_daging_sapi_asli_Padang.JPG?width=1024"},{"name":"Curry Laksa","rarity":"epic","id":"curry-laksa","subtitle":"Asian Classics","details":"Noodles in a rich coconut curry broth with prawns, fish cake, tofu puffs and bean sprouts, topped with herbs and a spoon of sambal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nyonya_Laksa.jpg?width=800"},{"name":"Char Kway Teow","rarity":"epic","id":"char-kway-teow","subtitle":"Asian Classics","details":"Flat rice noodles wok-fried over high heat with prawns, cockles, lap cheong sausage, egg, bean sprouts and chives in dark soy sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Char_kway_teow.jpg?width=1024"},{"name":"Nasi Goreng","rarity":"epic","id":"nasi-goreng","subtitle":"Asian Classics","details":"Indonesian fried rice darkened with sweet kecap manis, served with a fried egg, prawn crackers, pickles and often satay or fried chicken.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nasi_Goreng_Kampung_%2811967588375%29.jpg?width=1024"},{"name":"Kimchi Jjigae","rarity":"epic","id":"kimchi-jjigae","subtitle":"Asian Classics","details":"A bubbling Korean stew of aged kimchi, pork and tofu in a spicy broth, served boiling in a stone pot with a bowl of steamed rice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Korean_stew_dish_-_Kimchi-jjigae_Kimchi_Stew_2019_%2801%29.jpg?width=1024"},{"name":"Shoyu Ramen","rarity":"rare","id":"shoyu-ramen","subtitle":"Asian Classics","details":"Noodles in a clear soy-sauce seasoned broth, topped with chashu pork, bamboo shoots, nori, scallions and a halved seasoned egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg?width=1024"},{"name":"Miso Soup","rarity":"rare","id":"miso-soup","subtitle":"Asian Classics","details":"A light Japanese soup of dashi broth blended with miso paste, holding cubes of tofu, wakame seaweed and sliced scallions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Miso_Soup_001.jpg?width=1024"},{"name":"Shrimp Tempura","rarity":"rare","id":"shrimp-tempura","subtitle":"Asian Classics","details":"Prawns in a whisper-light batter, fried briefly until crisp and pale gold, served with tentsuyu dipping sauce and grated daikon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tempura_01.jpg?width=1024"},{"name":"Tonkatsu","rarity":"rare","id":"tonkatsu","subtitle":"Asian Classics","details":"A thick pork cutlet in crisp panko crumbs, fried until golden and served sliced with shredded cabbage, rice and tangy tonkatsu sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg?width=1024"},{"name":"Sukiyaki","rarity":"rare","id":"sukiyaki","subtitle":"Asian Classics","details":"Thin beef slices and vegetables simmered at the table in a sweet soy, mirin and sugar broth, dipped in beaten raw egg as they are eaten.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sukiyaki_01.jpg?width=1024"},{"name":"Shabu-Shabu","rarity":"rare","id":"shabu-shabu","subtitle":"Asian Classics","details":"Paper-thin beef and vegetables swished briefly in a pot of hot kombu broth, then dipped in ponzu or sesame sauce; named for its swishing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tajima%20Beef%20Shabu-Shabu%20Hot%20Pot%20%2825519259666%29.jpg?width=1024"},{"name":"Katsudon","rarity":"rare","id":"katsudon","subtitle":"Asian Classics","details":"A bowl of rice topped with a crisp pork cutlet simmered with onion in a dashi-soy sauce and set with softly cooked egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Katsudon_001.jpg?width=1024"},{"name":"Oyakodon","rarity":"rare","id":"oyakodon","subtitle":"Asian Classics","details":"Chicken and onion simmered in a sweet dashi-soy broth and bound with egg, served over rice; its name means parent-and-child bowl.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oyakodon_003.jpg?width=1024"},{"name":"Dan Dan Noodles","rarity":"rare","id":"dan-dan-noodles","subtitle":"Asian Classics","details":"Noodles dressed with chilli oil, Sichuan pepper, sesame and black vinegar, topped with spiced minced pork and greens; fiery and nutty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dan-dan_noodles%2C_Shanghai.jpg?width=1024"},{"name":"Zhajiangmian","rarity":"rare","id":"zhajiangmian","subtitle":"Asian Classics","details":"Thick wheat noodles topped with a rich, dark sauce of fermented black soybean paste and diced pork, plus shredded fresh vegetables.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Billyzhajiang1.jpg?width=1024"},{"name":"Hot and Sour Soup","rarity":"rare","id":"hot-and-sour-soup","subtitle":"Asian Classics","details":"A peppery, vinegar-sharp soup thick with wood-ear mushrooms, bamboo shoots, tofu and egg ribbons, warming and deeply savoury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ping_SJ_hot_%26_sour_soup.JPG?width=1024"},{"name":"Sweet and Sour Pork","rarity":"rare","id":"sweet-and-sour-pork","subtitle":"Asian Classics","details":"Crisp-fried pork pieces glazed in a glossy sweet and tangy sauce with pineapple, peppers and onion; a Cantonese restaurant classic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/菠萝咕噜肉.jpg?width=1024"},{"name":"General Tso's Chicken","rarity":"rare","id":"general-tsos-chicken","subtitle":"Asian Classics","details":"Crisp-fried chicken chunks in a glossy sweet, tangy and mildly spicy sauce, a Chinese-American favourite named for a Qing-dynasty general.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_preppybyday_4665999863--General_Tso%27s_Chicken.jpg?width=1024"},{"name":"Mongolian Beef","rarity":"rare","id":"mongolian-beef","subtitle":"Asian Classics","details":"Sliced beef seared in a hot wok with scallions in a sweet soy and garlic sauce, a Chinese-American stir-fry usually served over rice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian_Beef_with_rice_and_noodles.jpg?width=1024"},{"name":"Japchae","rarity":"uncommon","id":"japchae","subtitle":"Asian Classics","details":"Chewy glass noodles made from sweet potato starch, stir-fried with beef, mushrooms, spinach, carrots and onions in soy and sesame.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Polish_Korean_Cuisine_and_Culture_Exchanges_Gradmother%E2%80%99s_Recipes_05.jpg?width=1024"},{"name":"Tteokbokki","rarity":"uncommon","id":"tteokbokki","subtitle":"Asian Classics","details":"Chewy Korean rice cakes simmered in a sweet, spicy gochujang sauce with fish cakes and cabbage; a beloved street stall favourite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tteokbokki.JPG?width=1024"},{"name":"Samgyeopsal","rarity":"uncommon","id":"samgyeopsal","subtitle":"Asian Classics","details":"Thick slices of pork belly grilled at the table, cut with scissors and wrapped in lettuce with garlic, ssamjang and kimchi.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Samgyeopsal-gui.jpg?width=1024"},{"name":"Galbi","rarity":"uncommon","id":"galbi","subtitle":"Asian Classics","details":"Beef short ribs marinated in soy, pear, garlic and sesame, grilled until charred at the edges and served with rice and banchan sides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Korean.food-Galbi-03.jpg?width=1024"},{"name":"Sundubu Jjigae","rarity":"uncommon","id":"sundubu-jjigae","subtitle":"Asian Classics","details":"A spicy Korean stew of uncurdled soft tofu, seafood or pork and vegetables, served bubbling with an egg cracked in at the table.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sundubu-jjigae.jpg?width=1024"},{"name":"Bún Chả","rarity":"uncommon","id":"bun-cha","subtitle":"Asian Classics","details":"Grilled pork patties and sliced pork in a warm, tangy fish-sauce broth, served with rice vermicelli and a basket of fresh herbs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg?width=1024"},{"name":"Bún Bò Huế","rarity":"uncommon","id":"bun-bo-hue","subtitle":"Asian Classics","details":"A spicy beef and pork noodle soup from Huế, with round rice noodles, lemongrass heat and herbs, bolder and hotter than phở.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/B%C3%BAn_b%C3%B2_Hu%E1%BA%BF_-_Ch%E1%BB%A3_%C4%90%C3%B4ng_Ba_%282024%29_-_img_02.jpg?width=1024"},{"name":"Cao Lầu","rarity":"uncommon","id":"cao-lau","subtitle":"Asian Classics","details":"Thick chewy noodles from Hội An tossed with sliced pork, crisp croutons, bean sprouts and herbs in a small amount of rich sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg?width=1024"},{"name":"Cơm Tấm","rarity":"uncommon","id":"com-tam","subtitle":"Asian Classics","details":"Broken rice served with a grilled pork chop, shredded pork skin, a steamed egg-pork cake and pickles, with sweet fish sauce over all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/C%C6%A1m_T%E1%BA%A5m%2C_Da_Nang%2C_Vietnam.jpg?width=1024"},{"name":"Gỏi Cuốn","rarity":"uncommon","id":"goi-cuon","subtitle":"Asian Classics","details":"Fresh Vietnamese rice-paper rolls of prawns, pork, vermicelli and herbs, served cool with peanut hoisin or fish-sauce dip.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Homemade_spring_rolls_%287010969349%29.jpg?width=1024"},{"name":"Chả Giò","rarity":"uncommon","id":"cha-gio","subtitle":"Asian Classics","details":"Crisp Vietnamese fried spring rolls of pork, crab, mushrooms and glass noodles in rice paper, eaten with lettuce, herbs and fish sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%E1%BA%A3%20gi%C3%B2%20%28Vietnamese%20Spring%20Rolls%29%20-%2012.jpg?width=1024"},{"name":"Xiao Long Bao","rarity":"uncommon","id":"xiao-long-bao","subtitle":"Asian Classics","details":"Delicate Shanghai soup dumplings: pork and rich broth sealed in thin wheat wrappers, steamed and eaten with black vinegar and ginger.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_Xiaolongbao_from_The_Modern_Shanghai.jpg?width=1024"},{"name":"Wonton Soup","rarity":"uncommon","id":"wonton-soup","subtitle":"Asian Classics","details":"Silky pork and prawn wontons in a clear, hot broth with leafy greens and scallions, a Cantonese staple served in a deep bowl.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FOOD%20Wonton%20Soup.jpg?width=1024"},{"name":"Char Siu","rarity":"uncommon","id":"char-siu","subtitle":"Asian Classics","details":"Cantonese roast pork marinated in a sweet maltose glaze with five-spice, roasted until red at the edges and tender inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charsiu.jpg?width=1024"},{"name":"Hainanese Chicken Rice","rarity":"uncommon","id":"hainanese-chicken-rice","subtitle":"Asian Classics","details":"Chicken poached until silky, served with rice cooked in its broth and ginger, plus chilli sauce, ginger paste and dark soy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hainanese_Chicken_Rice.jpg?width=1024"},{"name":"Singapore Chili Crab","rarity":"uncommon","id":"singapore-chili-crab","subtitle":"Asian Classics","details":"Whole crab stir-fried in a sweet, savoury and gently spicy tomato-chilli sauce, thickened with egg; fried buns mop up the sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chilli_crab-02.jpg?width=1024"},{"name":"Chicken Satay","rarity":"uncommon","id":"chicken-satay","subtitle":"Asian Classics","details":"Skewers of marinated chicken grilled over charcoal until smoky at the edges, served with peanut sauce, cucumber and rice cakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chicken%20Satay%20With%20Peanut%20Sauce.jpg?width=1024"},{"name":"Gado-Gado","rarity":"uncommon","id":"gado-gado","subtitle":"Asian Classics","details":"An Indonesian salad of blanched vegetables, tofu, tempeh, potato and egg under a generous blanket of warm peanut sauce and crackers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gado_gado_jakarta.jpg?width=1024"},{"name":"Soto Ayam","rarity":"uncommon","id":"soto-ayam","subtitle":"Asian Classics","details":"A fragrant Indonesian chicken soup golden with turmeric, holding vermicelli, egg and shredded chicken, finished with lime and shallots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Soto_ayam.JPG?width=1024"},{"name":"Massaman Curry","rarity":"uncommon","id":"massaman-curry","subtitle":"Asian Classics","details":"A rich, mild curry of beef or chicken with potatoes, onions and roasted peanuts in coconut milk, warm with cinnamon and cardamom.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kaeng_matsaman_kai.JPG?width=1024"},{"name":"Panang Curry","rarity":"uncommon","id":"panang-curry","subtitle":"Asian Classics","details":"A thick, rich red curry with beef or chicken, coconut cream, ground peanuts and lime leaves, sweeter and drier than most Thai curries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panang_curry_%2842943883862%29.jpg?width=1024"},{"name":"Thai Fried Rice","rarity":"common","id":"thai-fried-rice","subtitle":"Asian Classics","details":"Jasmine rice stir-fried with egg, garlic, onion and chicken or prawns, seasoned with fish sauce and served with lime and cucumber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thaifriedrice.jpg?width=1024"},{"name":"Tom Kha Gai","rarity":"common","id":"tom-kha-gai","subtitle":"Asian Classics","details":"A gentle Thai soup of chicken in coconut milk with galangal, lemongrass and mushrooms, sour with lime and fragrant rather than fiery.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_preppybyday_4711943668--Tom_kha_gai.jpg?width=1024"},{"name":"Som Tam","rarity":"common","id":"som-tam","subtitle":"Asian Classics","details":"Shredded green papaya pounded with chillies, lime, peanuts, dried shrimp and long beans for a salad that is sour, salty, sweet and hot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2013_Tam_Lao.jpg?width=1024"},{"name":"Larb","rarity":"common","id":"larb","subtitle":"Asian Classics","details":"A salad of minced pork or chicken with lime juice, fish sauce, chillies, mint and shallots, warmed by toasted ground rice powder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LaoFood_LarbNeua.JPG?width=1024"},{"name":"Pad See Ew","rarity":"common","id":"pad-see-ew","subtitle":"Asian Classics","details":"Wide flat rice noodles stir-fried in dark sweet soy sauce with egg, Chinese broccoli and beef or chicken, charred at the edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pad_see_ew.jpg?width=1024"},{"name":"Pad Kee Mao","rarity":"common","id":"pad-kee-mao","subtitle":"Asian Classics","details":"Drunken noodles: broad rice noodles wok-tossed with chillies, garlic, Thai basil and vegetables in a dark, spicy-sweet sauce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sen_yai_phat_khi_mao.jpg?width=1024"},{"name":"Pad Kra Pao","rarity":"common","id":"pad-kra-pao","subtitle":"Asian Classics","details":"Minced pork or chicken stir-fried with holy basil, garlic and chillies, served over jasmine rice and often crowned with a fried egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Basil_fried_crispy_pork_with_rice_-_Chiang_Mai_-_2017-07-11_%28002%29.jpg?width=1024"},{"name":"Japanese Curry Rice","rarity":"common","id":"japanese-curry-rice","subtitle":"Asian Classics","details":"A thick, sweet-savoury curry sauce with beef, potatoes, carrots and onions ladled over white rice, with pink pickles alongside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beef_curry_rice_003.jpg?width=1024"},{"name":"Kitsune Udon","rarity":"common","id":"kitsune-udon","subtitle":"Asian Classics","details":"Thick wheat noodles in a clear dashi broth topped with a sheet of sweet simmered fried tofu, named for the foxes of folklore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Udon%20%28Kitsune%20udon%29%202.jpg?width=1024"},{"name":"Zaru Soba","rarity":"common","id":"zaru-soba","subtitle":"Asian Classics","details":"Chilled buckwheat noodles served on a bamboo tray with a soy-dashi dipping sauce, wasabi and scallions; eaten by dipping each mouthful.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zaru%20soba%20by%20spinachdip.jpg?width=1024"},{"name":"Nikujaga","rarity":"common","id":"nikujaga","subtitle":"Asian Classics","details":"A homestyle Japanese simmer of thin beef, potatoes, onions and carrots in a sweet soy-dashi broth, comfort food at its gentlest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Braised_pork_and_potatoes_%283089327692%29.jpg?width=1024"},{"name":"Agedashi Tofu","rarity":"common","id":"agedashi-tofu","subtitle":"Asian Classics","details":"Cubes of tofu lightly dusted, fried until crisp outside and silky within, served in a warm dashi-soy broth with ginger and scallion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agedashi_tofu%2C_fried_tofu_with_broth.jpg?width=1024"},{"name":"Chawanmushi","rarity":"common","id":"chawanmushi","subtitle":"Asian Classics","details":"A delicate steamed savoury egg custard holding chicken, prawn, mushroom and ginkgo nuts, eaten warm with a spoon from a lidded cup.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chawan-mushi.JPG?width=1024"},{"name":"Siu Mai","rarity":"common","id":"siu-mai","subtitle":"Asian Classics","details":"Open-topped Cantonese dim sum of pork and prawn in thin yellow wrappers, steamed in bamboo baskets and dotted with roe or pea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yellow_dim_sum_in_steamer_basket.jpg?width=1024"},{"name":"Lo Mein","rarity":"common","id":"lo-mein","subtitle":"Asian Classics","details":"Soft wheat noodles tossed in a soy-based sauce with vegetables, chicken, beef or prawns; a Chinese-American takeout staple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lo%20mein%2007.jpg?width=1024"},{"name":"Chow Mein","rarity":"common","id":"chow-mein","subtitle":"Asian Classics","details":"Stir-fried noodles tossed in a savoury soy-based sauce with vegetables and meat or tofu, prized for the smoky flavour of a hot wok.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Homemade_Chow_mein_with_shrimps_and_meat_with_a_choy_and_Choung.jpg/1280px-Homemade_Chow_mein_with_shrimps_and_meat_with_a_choy_and_Choung.jpg"},{"name":"Egg Fried Rice","rarity":"common","id":"egg-fried-rice","subtitle":"Asian Classics","details":"Rice stir-fried in a hot wok with beaten egg, spring onion and light seasoning, a simple staple that turns leftover grains golden.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Egg_Fried_Rice.jpg/1280px-Egg_Fried_Rice.jpg"},{"name":"Twice-Cooked Pork","rarity":"common","id":"twice-cooked-pork","subtitle":"Asian Classics","details":"Pork belly simmered, sliced, then stir-fried a second time with leeks, fermented bean paste and chillies for rich, layered heat.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Twice-cooked_Pork_%E5%9B%9E%E9%94%85%E8%82%89_%281648213963%29.jpg/1280px-Twice-cooked_Pork_%E5%9B%9E%E9%94%85%E8%82%89_%281648213963%29.jpg"},{"name":"Yu Xiang Eggplant","rarity":"common","id":"yu-xiang-eggplant","subtitle":"Asian Classics","details":"Silky eggplant braised in a glossy Sichuan-style sauce of garlic, chilli bean paste, vinegar and sugar, sweet, sour and gently hot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Qiezi.jpg/1280px-Qiezi.jpg"},{"name":"Clay Pot Rice","rarity":"common","id":"clay-pot-rice","subtitle":"Asian Classics","details":"Rice cooked in a clay pot until a crisp golden crust forms, topped with cured meats, chicken or mushrooms and sweetened soy sauce.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Claypot_Chicken_Rice%2C_Singapore.JPG/1280px-Claypot_Chicken_Rice%2C_Singapore.JPG"},{"name":"Salt and Pepper Squid","rarity":"common","id":"salt-and-pepper-squid","subtitle":"Asian Classics","details":"Tender squid in a light, crisp coating, wok-tossed with salt, cracked pepper, chilli and garlic until golden and aromatic.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/Salt_and_Pepper_Fresh_Squid_with_Steamed_Rice_-_CK_Bistro_2024-07-17.jpg/1280px-Salt_and_Pepper_Fresh_Squid_with_Steamed_Rice_-_CK_Bistro_2024-07-17.jpg"},{"name":"Roti Canai","rarity":"common","id":"roti-canai","subtitle":"Asian Classics","details":"Flaky, layered flatbread stretched paper-thin and griddled, torn apart by hand and served with curry or dhal for dipping.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/YosriRotiCanai.jpg/1280px-YosriRotiCanai.jpg"},{"name":"Nasi Lemak","rarity":"common","id":"nasi-lemak","subtitle":"Asian Classics","details":"Fragrant coconut rice served with sambal, fried anchovies, peanuts, cucumber and egg, a much-loved Malaysian combination.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas%2C_di_Penang_Summer_Restaurant.jpg/1280px-Nasi_Lemak_dengan_Chili_Nasi_Lemak_dan_Sotong_Pedas%2C_di_Penang_Summer_Restaurant.jpg"},{"name":"Kaya Toast","rarity":"common","id":"kaya-toast","subtitle":"Asian Classics","details":"Crisp toast spread with kaya, a golden coconut and egg jam, often served with a slab of butter and soft-boiled eggs on the side.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Kaya_toast_on_a_plate.jpg/1280px-Kaya_toast_on_a_plate.jpg"},{"name":"Mango Sticky Rice","rarity":"common","id":"mango-sticky-rice","subtitle":"Asian Classics","details":"Sweet glutinous rice soaked in coconut milk, served with ripe mango slices and a drizzle of salted coconut cream on top.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Mango_sticy_rice_%283859549574%29.jpg/1280px-Mango_sticy_rice_%283859549574%29.jpg"}]});
